{
    const str keyVaultUri = 'https://azr-servicebus-vault.vault.azure.net/';
    const str keyVaultNameD365FO = 'NDX365FO01NSPrimaryConnectionString';
    const str keyVaultSecretName = 'NDX365FO01NS-ConnectionString';
    const str azureQueueName = 'ax2009transferprodidentprocedure';

    protected static str connectionString;

    int maxRuntimeInMinutes;
    boolean isReadingFromQueue;
    int secStart;
    NoYes deleteActualData;
    NoYes runWithoutAction;
    protected System.Threading.Tasks.Task task1;

}

