/// <summary>
/// PaffH 27.07.22
/// </summary>
/// <param name = "_params">container</param>
/// <returns>container</returns>
public static container runableForAsyncCall(container _params)
{
    container conRet = conNull();
    int maxRuntimeInMinutes = conPeek(_params, 1);
    NoYes deleteActualData = conPeek(_params, 2);
    NoYes runWithoutAction = conPeek(_params, 3);
    NDXProdIdentProcedureFromAX2009 nDXProdIdentProcedureFromAX2009 = NDXProdIdentProcedureFromAX2009::construct();
    nDXProdIdentProcedureFromAX2009.ParmDeleteActualData(deleteActualData);
    nDXProdIdentProcedureFromAX2009.ParmRunWithoutAction(runWithoutAction);
    nDXProdIdentProcedureFromAX2009.ReadContractsFromQueue(maxRuntimeInMinutes);
    return conRet;
}

/// <summary>
/// PaffH 27.07.22
/// </summary>
/// <param name = "_result">AsyncTaskResult</param>
public static void asyncResult(AsyncTaskResult _result)
{
    container returnValue;

    if (_result != null)
    {
        returnValue = _result.getResult();
        str resultStr = conPeek(returnValue, 1);
        if (resultStr)
        {
            Info(resultStr);
        }
        System.Exception ex = _result.getException();
        if (ex)
        {
            Error(ex.Message);
        }
        container infoLogData = _result.getInfologData();
        if (conLen(infoLogData) > 0)
        {
            str infoStr = '';
            for (int i = 1; i<=conLen(infoLogData); i++)
            {
                infoStr += strFmt('%1;', conPeek(infoLogData, i));
            }
            Info(infoStr);
        }
    }
}

/// <summary>
/// PaffH 27.07.22
/// Read contracts (NDXProdIdentContract) from Azure Queue
/// </summary>
/// <param name = "_maxRuntimeInMinutes">int</param>
public void readContractsFromQueue(int _maxRuntimeInMinutes = 0)
{
    maxRuntimeInMinutes = _maxRuntimeInMinutes;

    InventTable inventTable;
    NDXProdIdentProcedureTable nDXProdIdentProcedureTable;
    NDXProdIdentProcedureLine1 nDXProdIdentProcedureLine1;
    Route route;
    RouteVersion routeVersion;
    boolean loopOK = true;
    int recCount1, recCount2, recCount3, countReadFromQueue, countRuns;
    IEnumerator enum, enum2, enum3;
    NDXProdIdentContract nDXProdIdentContract, nDXProdIdentContractLast;
    ProdIdentProcedureFromAX2009 prodIdentProcedureFromAX2009 = new ProdIdentProcedureFromAX2009(connectionString, azureQueueName);

    int sleepDuration = 1000;
    secStart = NDXHelperCommon::timeNow();
    int secStartRun = secStart;
    int secEnd, diffSec;
    str errInfo;
    NDXDataTransferErrorClass dataTransferError = NDXDataTransferErrorClass::construct(tableNum(NDXProdIdentProcedureTable));
    recCount1 = 0;
    recCount2 = 0;
    recCount3 = 0;
    countReadFromQueue = 0;
    countRuns = 0;
    int runtimeInMinutes;
    nDXProdIdentContractLast = null;
    isReadingFromQueue = true;
    info(strFmt('Start : [%1]', NDXHelperCommon::seconds2Str()));
    if (deleteActualData == NoYes::Yes)
    {
        this.deleteActualData();
        dataTransferError.deleteExistingLog();
    }
    while (loopOK)
    {
        nDXProdIdentProcedureTable = null;
        nDXProdIdentContract = prodIdentProcedureFromAX2009.Receive1MessageValuesD365FO(true).Contract;
        if (runWithoutAction == NoYes::Yes)
        {
            if (nDXProdIdentContract == null)
            {
                break;
            }
            else
            {
                continue;
            }
        }


        if (nDXProdIdentContract == null && nDXProdIdentContractLast == null)
        {
            secEnd = NDXHelperCommon::timeNow();
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }

        ++countReadFromQueue;
        if (nDXProdIdentContract == null && nDXProdIdentContractLast != null)
        {
            nDXProdIdentContractLast = null;
            ++countRuns;
            secEnd = NDXHelperCommon::timeNow();
            diffSec = secEnd - secStartRun;
            Info(strFmt('%1.) Dauer: [%2]', countRuns, NDXHelperCommon::seconds2Str(diffSec)));
            Info(strFmt('%1.) Azure-Queue Lesevorgänge: [%2]', countRuns, countReadFromQueue));
            Info(strFmt('%1.) Anzahl DS: Artikel[%2] [%3][%4]', countRuns, recCount1, recCount2, recCount3));
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }
        else
        {
            nDXProdIdentContractLast = nDXProdIdentContract;
            secStartRun = NDXHelperCommon::timeNow();
        }

        // read data from: NDXProdIdentProcedure - Contract
        try
        {
            IEnumerable tList = nDXProdIdentContract.NDXProdIdentProcedureContract;
            enum = tList.GetEnumerator();
            while (enum.moveNext())
            {
                ++recCount1;
                errInfo = '';
                inventTable = null;
                NDXProdIdentProcedureContract nDXProdIdentProcedureContract = enum.current;

                if (nDXProdIdentProcedureContract.ItemId != '')
                {
                    if (nDXProdIdentProcedureContract.DataAreaId != '' ||
                        nDXProdIdentProcedureContract.DataAreaId == curExt())
                    {
                        inventTable = InventTable::find(nDXProdIdentProcedureContract.ItemId, true);
                    }
                    else
                    {
                        changecompany(nDXProdIdentProcedureContract.DataAreaId)
                        {
                            inventTable = InventTable::find(nDXProdIdentProcedureContract.ItemId, true);
                        }
                    }
                }
                if (inventTable)
                {
                    changecompany(inventTable.DataAreaId)
                    {
                        nDXProdIdentProcedureTable = NDXProdIdentProcedureTable::findOrCreateInventTable(inventTable.RecId, true);
                    }

                }
                else
                {
                    continue;
                }

                // NDXProdIdentProcedureLine1
                IEnumerable tList2 = nDXProdIdentProcedureContract.NDXProdIdentProcedureLine1;
                enum2 = tList2.GetEnumerator();
                while (enum2.moveNext())
                {
                    NDXProdIdentProcedureLine1Contract nDXProdIdentProcedureLine1Contract = enum2.current;
                    changecompany(inventTable.DataAreaId)
                    {
                        // Status in inventTable
                        int prodIdentStatus = nDXProdIdentProcedureLine1Contract.ProdIdentStatus;
                        if (inventTable.NDX_ProdIdentStatus != prodIdentStatus)
                        {
                            ttsbegin;
                            inventTable.NDX_ProdIdentStatus = prodIdentStatus;
                            inventTable.write();
                            ttscommit;
                        }

                        nDXProdIdentProcedureLine1 = null;
                        route = null;
                        routeVersion = null;
                        if (!nDXProdIdentProcedureLine1Contract.ItemIsValid)
                        {
                            dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                "@NDX:NDXItemInvalidAX2009",
                                strFmt("@NDX:NDXItemPlaceholder",
                                nDXProdIdentProcedureLine1Contract.ItemId)));
                        }
                        if (nDXProdIdentProcedureLine1Contract.OprId == null)
                        {
                            dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                "@NDX:NDXOprIdMissingAX2009",
                                strFmt("@NDX:NDXRouteIdOprNum",
                                nDXProdIdentProcedureLine1Contract.RouteId,
                                nDXProdIdentProcedureLine1Contract.OprNum)));
                        }
                        else if (nDXProdIdentProcedureLine1Contract.RouteId != ''
                            && nDXProdIdentProcedureLine1Contract.OprNum != 0
                            && nDXProdIdentProcedureLine1Contract.OprId != '')
                        {
                            String20 oprId = nDXProdIdentProcedureLine1Contract.OprId;
                            // get oprId from mapping
                            NDXMappingDataTransferFromAX2009StringTypContract contract = new NDXMappingDataTransferFromAX2009StringTypContract();
                            contract.parmfieldTyp(NDXMappingDataFromAX2009FieldTyp::RouteOprId);
                            contract.parmFromStringValue(oprId);
                            contract.parminfoAdditional1(inventTable.ItemId);
                            contract.parminfoAdditional2(nDXProdIdentProcedureLine1Contract.RouteId);
                            NDXMappingDataTransferFromAX2009StringTyp nDXMappingDataTransferFromAX2009 = 
                                NDXMappingDataTransferFromAX2009StringTyp::findOrCreateFromContract(contract, true);
                            if (nDXMappingDataTransferFromAX2009 && nDXMappingDataTransferFromAX2009.MappingNotExist == NoYes::No)
                            {
                                oprId = nDXMappingDataTransferFromAX2009.ToStringValue;
                            }

                            select firstonly route where route.RouteId == nDXProdIdentProcedureLine1Contract.RouteId
                                && route.OprNum == nDXProdIdentProcedureLine1Contract.OprNum
                                && route.OprId == oprId;
                            if (route == null)
                            {
                                if (nDXProdIdentProcedureLine1Contract.RouteExists)
                                {
                                    dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                        "@NDX:NDXRouteNotFound",
                                        strFmt("@NDX:NDXRouteIdOprNumOprId",
                                        nDXProdIdentProcedureLine1Contract.RouteId,
                                        nDXProdIdentProcedureLine1Contract.OprNum,
                                        nDXProdIdentProcedureLine1Contract.OprId)));
                                }
                                else
                                {
                                    dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                        "@NDX:NDXRouteNotFoundAX2009",
                                        strFmt("@NDX:NDXRouteIdOprNumOprId",
                                        nDXProdIdentProcedureLine1Contract.RouteId,
                                        nDXProdIdentProcedureLine1Contract.OprNum,
                                        nDXProdIdentProcedureLine1Contract.OprId)));
                                }
                            }
                        }
                        if (nDXProdIdentProcedureLine1Contract.ItemId != ''
                            && nDXProdIdentProcedureLine1Contract.RouteId != '')
                        {
                            select firstonly routeVersion where routeVersion.ItemId == nDXProdIdentProcedureLine1Contract.ItemId
                                && routeVersion.RouteId == nDXProdIdentProcedureLine1Contract.RouteId;
                            if (routeVersion == null)
                            {
                                if (nDXProdIdentProcedureLine1Contract.RouteVersionExists)
                                {
                                    dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                    "@NDX:NDXRouteVersionNotFound",
                                    strFmt("@NDX:NDXItemIdRouteId",
                                    nDXProdIdentProcedureLine1Contract.ItemId,
                                    nDXProdIdentProcedureLine1Contract.RouteId)));
                                }
                                else
                                {
                                    dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                    "@NDX:NDXRouteVersionNotFoundAX2009",
                                    strFmt("@NDX:NDXItemIdRouteId",
                                    nDXProdIdentProcedureLine1Contract.ItemId,
                                    nDXProdIdentProcedureLine1Contract.RouteId)));
                                }

                            }
                        }
                        if (route && routeVersion)
                        {
                            // NDXProdIdentProcedureLine1
                            nDXProdIdentProcedureLine1 = NDXProdIdentProcedureLine1::findOrCreate(nDXProdIdentProcedureTable.RecId, routeVersion.RecId, route.RecId, false);
                            nDXProdIdentProcedureLine1.Freigabe = nDXProdIdentProcedureLine1Contract.Freigabe;
                            ttsbegin;
                            nDXProdIdentProcedureLine1.write();
                            ttscommit;

                            IEnumerable listNDXProdIdentBlock2ItemIdContract = nDXProdIdentProcedureLine1Contract.NDXProdIdentBlock2ItemIdContract;
                            IEnumerator enumListNDXProdIdentBlock2ItemIdContract = listNDXProdIdentBlock2ItemIdContract.GetEnumerator();
                            while (enumListNDXProdIdentBlock2ItemIdContract.MoveNext())
                            {
                                NDXProdIdentBlock2ItemIdContract nDXProdIdentBlock2ItemIdContract = enumListNDXProdIdentBlock2ItemIdContract.Current;
                                NDXProdIdentBlockTable nDXProdIdentBlockTable;
                                if (nDXProdIdentBlock2ItemIdContract.BlockId.Length > 0)
                                {
                                    // NDXProdIdentBlockTable
                                    NDXProdIdentBlockTableContract nDXProdIdentBlockTableContract = nDXProdIdentBlock2ItemIdContract.NDXProdIdentBlockTableContract;
                                    if (nDXProdIdentBlockTableContract)
                                    {
                                        nDXProdIdentBlockTable = NDXProdIdentBlockTable::findOrCreate(nDXProdIdentBlockTableContract.Id, false);
                                        nDXProdIdentBlockTable.BlockType = nDXProdIdentBlockTableContract.BlockType;
                                        nDXProdIdentBlockTable.Name = nDXProdIdentBlockTableContract.Name;
                                        ttsbegin;
                                        nDXProdIdentBlockTable.write();
                                        ttscommit;

                                        // NDXProdIdentBlockLine
                                        IEnumerable listNDXProdIdentBlockLineContract = nDXProdIdentBlockTableContract.NDXProdIdentBlockLineContract;
                                        IEnumerator enumListNDXProdIdentBlockLineContract = listNDXProdIdentBlockLineContract.GetEnumerator();
                                        while (enumListNDXProdIdentBlockLineContract.MoveNext())
                                        {
                                            NDXProdIdentBlockLineContract nDXProdIdentBlockLineContract = enumListNDXProdIdentBlockLineContract.Current;
                                            NDXProdIdentBlockLine nDXProdIdentBlockLine = NDXProdIdentBlockLine::findOrCreate(
                                            nDXProdIdentBlockTable.RecId,
                                            nDXProdIdentBlockLineContract.Name,
                                            false);
                                            nDXProdIdentBlockLine.StaticMethodName = nDXProdIdentBlockLineContract.StaticMethodName;
                                            nDXProdIdentBlockLine.ClassName = nDXProdIdentBlockLineContract.ClassName;
                                            nDXProdIdentBlockLine.RetValType = nDXProdIdentBlockLineContract.RetValType;
                                            nDXProdIdentBlockLine.Checked = nDXProdIdentBlockLineContract.Checked;
                                            nDXProdIdentBlockLine.ParmType_Var1 = nDXProdIdentBlockLineContract.ParmType_Var1;
                                            nDXProdIdentBlockLine.RetValExample = nDXProdIdentBlockLineContract.RetValExample;
                                            nDXProdIdentBlockLine.TextType = nDXProdIdentBlockLineContract.TextTyp;
                                            nDXProdIdentBlockLine.PicturePath = nDXProdIdentBlockLineContract.PicturePath;
                                            nDXProdIdentBlockLine.ConstText = nDXProdIdentBlockLineContract.ConstText;
                                            ttsbegin;
                                            nDXProdIdentBlockLine.write();
                                            ttscommit;
                                        }
                                    }
                                    else
                                    {
                                        nDXProdIdentBlockTable = NDXProdIdentBlockTable::findOrCreate(nDXProdIdentBlock2ItemIdContract.BlockId);
                                    }

                                    // NDXProdIdentBlock2ItemId
                                    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId = NDXProdIdentBlock2ItemId::findOrCreate(
                                    nDXProdIdentProcedureLine1.RecId,
                                    nDXProdIdentBlock2ItemIdContract.IDSort,
                                    nDXProdIdentBlock2ItemIdContract.SubId,
                                    nDXProdIdentBlockTable.RecId,
                                    nDXProdIdentBlock2ItemIdContract.BlockIdFieldName,
                                    false);
                                    nDXProdIdentBlock2ItemId.IsFreeText = nDXProdIdentBlock2ItemIdContract.IsFreeText;
                                    nDXProdIdentBlock2ItemId.FreeTextField = nDXProdIdentBlock2ItemIdContract.FreeTextField;
                                    ttsbegin;
                                    nDXProdIdentBlock2ItemId.write();
                                    ttscommit;
                                }
                            }

                            // NDXProdIdentProcedureLine2
                            IEnumerable tList3 = nDXProdIdentProcedureLine1Contract.NDXProdIdentProcedureLine2;
                            enum3 = tList3.GetEnumerator();
                            while (enum3.moveNext())
                            {
                                NDXProdIdentProcedureLine2Contract nDXProdIdentProcedureLine2Contract = enum3.current;
                                NDXProdIdentProcedureLine2 nDXProdIdentProcedureLine2 = NDXProdIdentProcedureLine2::findOrCreate(
                                    nDXProdIdentProcedureLine1.RecId,
                                    nDXProdIdentProcedureLine2Contract.IDSort, true);


                                // UnitConvert
                                UnitConvertContract unitConvertContract = nDXProdIdentProcedureLine2Contract.UnitConvertContract;
                                if (unitConvertContract)
                                {
                                    Query q = new Query();
                                    QueryBuildDataSource qbdsEcoResProduct = q.addDataSource(tableNum(EcoResProduct));
                                    qbdsEcoResProduct.addRange(fieldNum(EcoResProduct, RecId)).value(queryValue(inventTable.Product));
                                    QueryBuildDataSource qbdsUnitOfMeasureConversion = qbdsEcoResProduct.addDataSource(tableNum(UnitOfMeasureConversion));
                                    qbdsUnitOfMeasureConversion.relations(true);
                                    qbdsUnitOfMeasureConversion.fetchMode(QueryFetchMode::One2One);
                                    QueryBuildDataSource qbdsUnitOfMeasureFrom = qbdsUnitOfMeasureConversion.addDataSource(tableNum(UnitOfMeasure));
                                    qbdsUnitOfMeasureFrom.addLink(fieldNum(UnitOfMeasureConversion, FromUnitOfMeasure), fieldNum(UnitOfMeasure, RecId));
                                    qbdsUnitOfMeasureFrom.fetchMode(QueryFetchMode::One2One);
                                    QueryBuildDataSource qbdsUnitOfMeasureTo = qbdsUnitOfMeasureConversion.addDataSource(tableNum(UnitOfMeasure));
                                    qbdsUnitOfMeasureTo.addLink(fieldNum(UnitOfMeasureConversion, ToUnitOfMeasure), fieldNum(UnitOfMeasure, RecId));
                                    qbdsUnitOfMeasureTo.fetchMode(QueryFetchMode::One2One);

                                    qbdsUnitOfMeasureFrom.addRange(fieldNum(UnitOfMeasure, Symbol)).value(queryValue(unitConvertContract.FromUnit));
                                    qbdsUnitOfMeasureTo.addRange(fieldNum(UnitOfMeasure, Symbol)).value(queryValue(unitConvertContract.ToUnit));
                                    qbdsUnitOfMeasureConversion.addRange(fieldNum(UnitOfMeasureConversion, Factor)).value(queryValue(unitConvertContract.Factor));

                                    QueryRun qr = new QueryRun(q);
                                    qr.next();
                                    UnitOfMeasureConversion unitOfMeasureConversion = qr.get(tableNum(UnitOfMeasureConversion));
                                    UnitOfMeasure unitOfMeasureFrom = qr.get(tableNum(UnitOfMeasure), 1);
                                    UnitOfMeasure unitOfMeasureTo = qr.get(tableNum(UnitOfMeasure), 2);

                                    if (unitOfMeasureFrom.Symbol == unitConvertContract.FromUnit
                                        && unitOfMeasureTo.Symbol == unitConvertContract.ToUnit)
                                    {
                                        nDXProdIdentProcedureLine2.UnitOfMeasureConversion = unitOfMeasureConversion.RecId;
                                    }
                                    else
                                    {
                                        qbdsUnitOfMeasureFrom.clearRanges();
                                        qbdsUnitOfMeasureFrom.addRange(fieldNum(UnitOfMeasure, Symbol)).value(queryValue(unitConvertContract.ToUnit));
                                        qbdsUnitOfMeasureTo.clearRanges();
                                        qbdsUnitOfMeasureTo.addRange(fieldNum(UnitOfMeasure, Symbol)).value(queryValue(unitConvertContract.FromUnit));
                                        qr = new QueryRun(q);
                                        qr.next();
                                        unitOfMeasureConversion = qr.get(tableNum(UnitOfMeasureConversion));
                                        unitOfMeasureFrom = qr.get(tableNum(UnitOfMeasure), 1);
                                        unitOfMeasureTo = qr.get(tableNum(UnitOfMeasure), 2);

                                        if (unitOfMeasureFrom.Symbol == unitConvertContract.ToUnit
                                        && unitOfMeasureTo.Symbol == unitConvertContract.FromUnit)
                                        {
                                            nDXProdIdentProcedureLine2.UnitOfMeasureConversion = unitOfMeasureConversion.RecId;
                                        }
                                        else
                                        {
                                            dataTransferError.addError(nDXProdIdentProcedureTable.RecId, NDXErrorMessageClass::construct(
                                                "@NDX:NDXUnitOfMeasureNotFound",
                                                strFmt("@NDX:NDXFromUnitToUnitFactor",
                                                unitConvertContract.FromUnit,
                                                unitConvertContract.ToUnit,
                                                unitConvertContract.Factor)));
                                        }
                                    }
                                }

                                // NDXProdIdentLabel
                                NDXProdIdentLabelContract nDXProdIdentLabelContract = nDXProdIdentProcedureLine2Contract.NDXProdIdentLabelContract;
